package grouping

import (
	"regexp"
	"strings"
)

// NormalizeFunction removes the parts of a Go function name that change
// when unrelated code changes, so the same code keeps the same name:
//
//	(*Cart).Checkout.func2      -> (*Cart).Checkout.func   closure numbers shift when a closure is added above
//	(*Cart).Checkout.func1.3    -> (*Cart).Checkout.func.func   nested closures
//	(*Server).Handle-fm         -> (*Server).Handle   method value wrapper generated by the compiler
//	Map[go.shape.int]           -> Map[...]           generic instantiation details
//	handler·0x1f3a              -> handler·0x?        addresses, should any appear
func NormalizeFunction(fn string) string {
	fn = strings.TrimSuffix(fn, "-fm")
	fn = genericArgs.ReplaceAllString(fn, "[...]")
	fn = hexAddress.ReplaceAllString(fn, "0x?")

	parts := strings.Split(fn, ".")
	for i, p := range parts {
		if closureName.MatchString(p) || allDigits.MatchString(p) {
			parts[i] = "func"
		}
	}
	return strings.Join(parts, ".")
}

var (
	closureName = regexp.MustCompile(`^func\d+$`)
	allDigits   = regexp.MustCompile(`^\d+$`)
	genericArgs = regexp.MustCompile(`\[[^\]]*\]`)
	hexAddress  = regexp.MustCompile(`0x[0-9a-fA-F]+`)
)

// Rules applied by NormalizeMessage, in order. Earlier rules protect
// patterns that a later, broader rule would only partly replace: a UUID
// contains numbers, an IP address is numbers and dots.
var messageRules = []struct {
	re   *regexp.Regexp
	with string
}{
	{regexp.MustCompile(`(?i)\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b`), "<uuid>"},
	{regexp.MustCompile(`[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}`), "<email>"},
	{regexp.MustCompile(`\b\d{1,3}(?:\.\d{1,3}){3}(?::\d+)?\b`), "<ip>"},
	{regexp.MustCompile(`0x[0-9a-fA-F]+`), "<hex>"},
	{regexp.MustCompile(`"[^"]*"|'[^']*'|` + "`[^`]*`"), "<str>"},
	// Durations glued to their unit, Go style included: 2300ms, 2.5s, 1m30s.
	{regexp.MustCompile(`\b(?:\d+(?:\.\d+)?(?:ns|us|ms|s|m|h))+\b`), "<dur>"},
	// Sizes glued to their unit: 512kb, 1.5GiB.
	{regexp.MustCompile(`(?i)\b\d+(?:\.\d+)?(?:b|kb|mb|gb|tb|kib|mib|gib|tib)\b`), "<size>"},
	// Standalone numbers, decimals included. Digits inside words (utf8,
	// http2, user123) are kept: they are usually part of a name.
	{regexp.MustCompile(`\b\d+(?:\.\d+)?\b`), "<n>"},
	{regexp.MustCompile(`\s+`), " "},
}

// Long hex runs (hashes, trace IDs, tokens) are replaced right after the
// 0x rule. Go's regexp has no lookahead, so "8+ hex characters containing
// both a digit and a letter" is checked in code: pure digits are left for
// the number rule, and pure-letter words like "deadbeef" or "facade" stay.
var hexRun = regexp.MustCompile(`\b[0-9a-fA-F]{8,}\b`)

const hexRunsAfter = 3 // index of the 0x rule in messageRules

func replaceHexRun(s string) string {
	hasDigit := strings.ContainsAny(s, "0123456789")
	hasLetter := strings.ContainsAny(s, "abcdefABCDEF")
	if hasDigit && hasLetter {
		return "<hex>"
	}
	return s
}

// maxNormalizedMessage bounds the text that goes into the hash. Two messages
// that agree on their first 512 normalized bytes describe the same problem.
const maxNormalizedMessage = 512

// NormalizeMessage replaces the parts of a message that vary between
// occurrences of the same problem: IDs, numbers, addresses, quoted values.
//
//	"timeout after 2300ms calling 10.0.0.12:5432" -> "timeout after <n>ms calling <ip>"
//	`user "jdoe" not found`                       -> "user <str> not found"
func NormalizeMessage(msg string) string {
	for i, r := range messageRules {
		msg = r.re.ReplaceAllString(msg, r.with)
		if i == hexRunsAfter {
			msg = hexRun.ReplaceAllStringFunc(msg, replaceHexRun)
		}
	}
	msg = strings.TrimSpace(msg)
	if len(msg) > maxNormalizedMessage {
		msg = msg[:maxNormalizedMessage]
	}
	return msg
}
